CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE fetch_runs(run_id TEXT PRIMARY KEY, started_at TEXT NOT NULL, ended_at TEXT, status TEXT NOT NULL CHECK(status IN ('running','success','partial','failed')), requested_source TEXT, summary_json TEXT NOT NULL DEFAULT '{}', warnings_json TEXT NOT NULL DEFAULT '[]', error_json TEXT);
CREATE TABLE feed_polls(poll_id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL REFERENCES fetch_runs(run_id), feed_id TEXT NOT NULL, source TEXT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, status TEXT NOT NULL CHECK(status IN ('running','not_modified','success','failed')), http_status INTEGER, attempt_count INTEGER NOT NULL DEFAULT 0, sent_etag TEXT, sent_last_modified TEXT, received_etag TEXT, received_last_modified TEXT, response_hash TEXT, response_bytes INTEGER, raw_item_count INTEGER, parsed_item_count INTEGER, valid_item_count INTEGER, quarantined_item_count INTEGER, feed_last_build_date TEXT, warning_json TEXT NOT NULL DEFAULT '[]', error_json TEXT);
CREATE INDEX feed_polls_feed_idx ON feed_polls(feed_id,poll_id DESC); CREATE INDEX feed_polls_run_idx ON feed_polls(run_id);
CREATE TABLE feed_state(feed_id TEXT PRIMARY KEY, source TEXT NOT NULL, url TEXT NOT NULL, etag TEXT, last_modified TEXT, last_response_hash TEXT, last_checked_at TEXT, last_successful_poll_at TEXT, last_item_count INTEGER, newest_published_at TEXT, consecutive_failures INTEGER NOT NULL DEFAULT 0, last_error_json TEXT);
CREATE TABLE raw_payloads(content_hash TEXT PRIMARY KEY, compression TEXT NOT NULL CHECK(compression='gzip'), payload BLOB NOT NULL, uncompressed_bytes INTEGER NOT NULL, first_poll_id INTEGER NOT NULL REFERENCES feed_polls(poll_id), first_observed_at TEXT NOT NULL);
CREATE TABLE sightings(sighting_id INTEGER PRIMARY KEY AUTOINCREMENT, poll_id INTEGER NOT NULL REFERENCES feed_polls(poll_id), feed_id TEXT NOT NULL, source TEXT NOT NULL, source_id TEXT NOT NULL, item_position INTEGER NOT NULL CHECK(item_position>0), publisher_order INTEGER, observed_at TEXT NOT NULL, normalized_json TEXT NOT NULL CHECK(json_valid(normalized_json)), raw_metadata_json TEXT NOT NULL CHECK(json_valid(raw_metadata_json)), raw_item_json TEXT NOT NULL CHECK(json_valid(raw_item_json)), UNIQUE(feed_id,source_id,poll_id));
CREATE TABLE articles(source TEXT NOT NULL, source_id TEXT NOT NULL, snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)), published_at TEXT NOT NULL, last_changed_at TEXT NOT NULL, canonical_url TEXT, content_hash TEXT NOT NULL, last_enrichment_status TEXT, last_enrichment_success_at TEXT, PRIMARY KEY(source,source_id));
CREATE INDEX articles_published_idx ON articles(published_at); CREATE INDEX articles_changed_idx ON articles(last_changed_at); CREATE INDEX articles_url_idx ON articles(canonical_url);
CREATE TABLE article_versions(version_id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT NOT NULL, source_id TEXT NOT NULL, content_hash TEXT NOT NULL, observed_at TEXT NOT NULL, snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)), FOREIGN KEY(source,source_id) REFERENCES articles(source,source_id));
CREATE TABLE appearances(appearance_id INTEGER PRIMARY KEY AUTOINCREMENT, poll_id INTEGER NOT NULL REFERENCES feed_polls(poll_id), source TEXT NOT NULL, source_id TEXT NOT NULL, surface_id TEXT NOT NULL, surface TEXT NOT NULL, surface_section TEXT, position INTEGER NOT NULL, publisher_order INTEGER, is_super_article INTEGER, observed_at TEXT NOT NULL, UNIQUE(poll_id,surface_id,position));
CREATE TABLE quarantine(quarantine_id INTEGER PRIMARY KEY AUTOINCREMENT,poll_id INTEGER REFERENCES feed_polls(poll_id),feed_id TEXT NOT NULL,source TEXT NOT NULL,item_position INTEGER,stage TEXT NOT NULL CHECK(stage IN ('http','feed','item','replay','enrichment')),error_code TEXT NOT NULL,error_json TEXT NOT NULL,raw_item_json TEXT,created_at TEXT NOT NULL,resolved_at TEXT);
CREATE TABLE enrichment_jobs(job_id INTEGER PRIMARY KEY AUTOINCREMENT,source TEXT NOT NULL,source_id TEXT NOT NULL,purpose TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,last_attempt_at TEXT,last_success_at TEXT,next_retry_at TEXT,etag TEXT,last_modified TEXT,parser_version TEXT,error_json TEXT,UNIQUE(source,source_id,purpose));
